{"version":3,"sources":["../scss/publications_add.scss","publications_add.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAGA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,gBAAA;ACFF;ADIE;EACE,aAAA;EACA,mBAAA;EACA,SAAA;EACA,eAAA;EACA,yBAAA;ACFJ;ADII;EACE,eAAA;EEhBF,uCAAA;EACA,gBFgBsC;EEftC,kBAAA;EACA,YCHW;EDIX,eFagC;ACEpC;ADDM;EACA,UAAA;ACGN;ADEE;;EAEE,gBAAA;EACA,WAAA;EACA,YAAA;EACA,yBAAA;EACA,kBAAA;EE9BA,uCAAA;EACA,gBF8BoC;EE7BpC,kBAAA;EACA,YCHW;EDIX,eF2B8B;ACIlC;ADHI;;EACE,yBAAA;ACMN;ADHI;EEpCA,uCAAA;EACA,gBFoCgC;EEnChC,kBAAA;EACA,cFkCiB;EEjCjB,eFiC0B;ACU9B;ADXI;;EEpCA,uCAAA;EACA,gBFoCgC;EEnChC,kBAAA;EACA,cFkCiB;EEjCjB,eFiC0B;ACU9B;ADNE;EACE,gBAAA;ACQJ;;ADHA;EACE,kBAAA;EACA,yBAAA;EACA,kBAAA;EACA,gBAAA;ACMF;ADLE;EACE,gBAAA;EACA,gBAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;EACA,kBAAA;ACOJ;ADHI;EACE,qBAAA;EACA,UAAA;EACA,cAAA;ACKN;;ADAA;EACE,wBAAA;EACA,qBAAA;EACA,UAAA;EACA,kBAAA;EACA,MAAA;EACA,QAAA;EACA,WAAA;EACA,YAAA;EACA,8BAAA;EACA,eAAA;EACA,UAAA;ACGF;ADDE;EAEE,WAAA;EACA,cAAA;EACA,WAAA;EACA,WAAA;EACA,gBAAA;EACA,kBAAA;EACA,QAAA;EACA,QAAA;EACA,UAAA;EACA,wBAAA;ACEJ;ADAE;EACE,yBAAA;ACEJ;;ADEA;EACE;IACE,eAAA;ECCF;EDAE;IACE,eAAA;ECEJ;EDCE;IACE,sBAAA;IACA,oBAAA;ECCJ;EDAI;IACE,aAAA;ECEN;AACF","file":"publications_add.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.main__info {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  max-width: 530px;\n\n  & label {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    flex-wrap: wrap;\n    justify-content: flex-end;\n\n    & p {\n      flex: 0 0 200px;\n      @include fonts($defaultColor, 14px, 400);\n      & span {\n      color: red;\n    }\n    }\n  }\n\n  & input,\n  textarea {\n    max-width: 320px;\n    width: 100%;\n    padding: 7px;\n    border: 1px solid $gray;\n    border-radius: 7px;\n    @include fonts($defaultColor, 14px, 400);\n    &:focus {\n      border: 1px solid #3779eb;\n    }\n\n    &::placeholder {\n      @include fonts(#545454, 14px, 400);\n    }\n  }\n\n  & button {\n    max-width: 320px;\n  }\n}\n\n\n.photo_img {\n  position: relative;\n  border: 1px solid $asideLinksColor;\n  border-radius: 3px;\n  max-width: 120px;\n  & img {\n    max-width: 120px;\n    max-height: 85px;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n    border-radius: 3px;\n  }\n\n  &:hover {\n    .delete_img {\n      transition: 0.3s ease;\n      opacity: 1;\n      display: block;\n    }\n  }\n}\n\n.delete_img {\n  border-radius: 0 3px 0 0;\n  transition: 0.3s ease;\n  opacity: 0;\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 15px;\n  height: 15px;\n  background: rgb(0, 0, 0, 0.5);\n  cursor: pointer;\n  z-index: 1;\n\n  &::after,\n  &::before {\n    content: \"\";\n    display: block;\n    width: 100%;\n    height: 2px;\n    background: #fff;\n    position: absolute;\n    top: 45%;\n    right: 0;\n    z-index: 1;\n    transform: rotate(45deg);\n  }\n  &::before {\n    transform: rotate(-45deg);\n  }\n}\n\n@media (max-width: 992px) {\n  .main__info {\n    max-width: none;\n    & input {\n      max-width: none;\n    }\n\n    & label {\n      flex-direction: column;\n      align-items: initial;\n      & p {\n        flex: initial;\n      }\n    }\n  }\n}\n",".main__info {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  max-width: 530px;\n}\n.main__info label {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n}\n.main__info label p {\n  flex: 0 0 200px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.main__info label p span {\n  color: red;\n}\n.main__info input,\n.main__info textarea {\n  max-width: 320px;\n  width: 100%;\n  padding: 7px;\n  border: 1px solid #D4D4D4;\n  border-radius: 7px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.main__info input:focus,\n.main__info textarea:focus {\n  border: 1px solid #3779eb;\n}\n.main__info input::placeholder,\n.main__info textarea::placeholder {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n}\n.main__info button {\n  max-width: 320px;\n}\n\n.photo_img {\n  position: relative;\n  border: 1px solid #307792;\n  border-radius: 3px;\n  max-width: 120px;\n}\n.photo_img img {\n  max-width: 120px;\n  max-height: 85px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n  border-radius: 3px;\n}\n.photo_img:hover .delete_img {\n  transition: 0.3s ease;\n  opacity: 1;\n  display: block;\n}\n\n.delete_img {\n  border-radius: 0 3px 0 0;\n  transition: 0.3s ease;\n  opacity: 0;\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 15px;\n  height: 15px;\n  background: rgba(0, 0, 0, 0.5);\n  cursor: pointer;\n  z-index: 1;\n}\n.delete_img::after, .delete_img::before {\n  content: \"\";\n  display: block;\n  width: 100%;\n  height: 2px;\n  background: #fff;\n  position: absolute;\n  top: 45%;\n  right: 0;\n  z-index: 1;\n  transform: rotate(45deg);\n}\n.delete_img::before {\n  transform: rotate(-45deg);\n}\n\n@media (max-width: 992px) {\n  .main__info {\n    max-width: none;\n  }\n  .main__info input {\n    max-width: none;\n  }\n  .main__info label {\n    flex-direction: column;\n    align-items: initial;\n  }\n  .main__info label p {\n    flex: initial;\n  }\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}